
class Twitter {
    
        private static class Tweet {
                int id;
                        int time;

                                public Tweet(int id, int time) {
                                            this.id = id;
                                                        this.time = time;
                                                                }
                                                                    }

                                                                        private static class User {
                                                                                int userId;
                                                                                        Set<Integer> followed;
                                                                                                List<Tweet> tweets;

                                                                                                        public User(int userId) {
                                                                                                                    this.userId = userId;
                                                                                                                                this.followed = new HashSet<>();
                                                                                                                                            this.tweets = new LinkedList<>();
                                                                                                                                                        this.followed.add(userId); // Follow self
                                                                                                                                                                }
                                                                                                                                                                    }

                                                                                                                                                                        private final Map<Integer, User> userMap;
                                                                                                                                                                            private int timeCounter;

                                                                                                                                                                                public Twitter() {
                                                                                                                                                                                        this.userMap = new HashMap<>();
                                                                                                                                                                                                this.timeCounter = 0;
                                                                                                                                                                                                    }

                                                                                                                                                                                                        public void postTweet(int userId, int tweetId) {
                                                                                                                                                                                                                userMap.putIfAbsent(userId, new User(userId));
                                                                                                                                                                                                                        userMap.get(userId).tweets.add(0, new Tweet(tweetId, timeCounter++));
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                public List<Integer> getNewsFeed(int userId) {
                                                                                                                                                                                                                                        if (!userMap.containsKey(userId)) return new ArrayList<>();
                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                        // Using Integer.compare protects against potential subtraction overflow bugs
                                                                                                                                                                                                                                                                PriorityQueue<Tweet> pq = new PriorityQueue<>((a, b) -> Integer.compare(b.time, a.time));
                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                for (int followeeId : userMap.get(userId).followed) {
                                                                                                                                                                                                                                                                                            int count = 0;
                                                                                                                                                                                                                                                                                                        for (Tweet t : userMap.get(followeeId).tweets) {
                                                                                                                                                                                                                                                                                                                        pq.offer(t);
                                                                                                                                                                                                                                                                                                                                        if (++count >= 10) break;
                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                    List<Integer> res = new ArrayList<>();
                                                                                                                                                                                                                                                                                                                                                                            int count = 0;
                                                                                                                                                                                                                                                                                                                                                                                    while (!pq.isEmpty() && count < 10) {
                                                                                                                                                                                                                                                                                                                                                                                                res.add(pq.poll().id);
                                                                                                                                                                                                                                                                                                                                                                                                            count++;
                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                            return res;
                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                    public void follow(int followerId, int followeeId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            userMap.putIfAbsent(followerId, new User(followerId));
                                                                                                                                                                                                                                                                                                                                                                                                                                                    userMap.putIfAbsent(followeeId, new User(followeeId));
                                                                                                                                                                                                                                                                                                                                                                                                                                                            userMap.get(followerId).followed.add(followeeId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    public void unfollow(int followerId, int followeeId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!userMap.containsKey(followerId) || followerId == followeeId) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    userMap.get(followerId).followed.remove(followeeId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

